{"code": "# From previous tool call we know neighbors are:
neighbors = [1, 2, 4, 5, 6, 7, 9, 10, 11, 12, 14, 15, 16, 17, 19, 20, 23, 24, 25, 26, 29, 31, 32, 33, 34, 35, 39, 40, 41, 44, 45, 46, 48, 49]
# Count triangles through node 21 (i.e., find all pairs of neighbors that are connected)

triangle_count = 0
triangles = []

n_neighbors = len(neighbors)
for i in range(n_neighbors):
    for j in range(i+1, n_neighbors):
        u = neighbors[i]
        v = neighbors[j]
        if has_edge(u, v):
            # Found a triangle: 21-u-v
            triangles.append([u, v, 21])
            triangle_count += 1

result = {
    "count": triangle_count,
    "triangles": sorted(triangles)
}
print(result["count"])"}
